css:
.pe-root.pe-n-n0{display:flex;flex-direction:column;gap:16px;align-items:stretch;justify-content:flex-start;flex-wrap:nowrap}
.pe-root .pe-n-n5{aspect-ratio:4;background-color:rgb(10, 20, 30);border-color:transparent}.pe-root .pe-n-n5>.pe-in{display:flex;flex-direction:column;gap:16px;align-items:stretch;justify-content:flex-start;flex-wrap:nowrap;max-width:753px;margin-inline:auto}
@media (max-width:479.98px){.pe-root .pe-n-n5>.pe-in{gap:285px;align-items:baseline}}
.pe-root .pe-n-n6{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr) minmax(0,1fr) minmax(0,1fr) minmax(0,1fr) minmax(0,1fr) minmax(0,1fr) minmax(0,1fr) minmax(0,1fr) minmax(0,1fr) minmax(0,1fr) minmax(0,1fr);grid-template-rows:minmax(40px,auto) minmax(40px,auto) minmax(40px,auto) minmax(40px,auto) minmax(40px,auto);grid-auto-rows:minmax(40px,auto);column-gap:339px;row-gap:375px;background-image:url("/b%20c.png");background-size:auto;opacity:0.57;--a:1px}
@media (max-width:899.98px){.pe-root .pe-n-n6{row-gap:285px}}
@media (max-width:479.98px){.pe-root .pe-n-n6{rotate:-215.74deg;z-index:-34;font-family:system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;line-height:2}}
.pe-root .pe-n-n7{grid-column:span 1;grid-row:span 1;max-height:53px;font-weight:500}
@media (max-width:479.98px){.pe-root .pe-n-n7{grid-column:span 4;grid-row:span 8}}
.pe-root .pe-n-n8{grid-column:3 / span 2;grid-row:5 / span 1;background-repeat:repeat-x;box-shadow:0 12px 32px rgba(0,0,0,.14);--a:1px}
@media (max-width:479.98px){.pe-root .pe-n-n8{grid-column:2 / span 5;grid-row:5 / span 4}}
.pe-root a.pe-n-nc{height:fit-content;flex:0 0 auto;z-index:206;padding:62px 79px 1px 3px;border-width:18.21px;border-style:solid;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,"Liberation Mono",monospace;font-style:normal}
@media (max-width:899.98px){.pe-root a.pe-n-nc{background-size:cover;outline-width:18.21px;outline-style:solid;outline-offset:-9.1px;border-width:unset;border-style:unset}}
.pe-root .pe-n-nk{align-self:stretch;background-position:bottom;border-width:8px;border-style:solid;border-radius:6px 53px 44px 19px;font-weight:900;letter-spacing:10.05px;text-transform:lowercase;font-style:italic}
@media (min-width:900px){.pe-root .pe-hide-d{display:none!important}}
@media (min-width:480px) and (max-width:899.98px){.pe-root .pe-hide-t{display:none!important}}
@media (max-width:479.98px){.pe-root .pe-hide-m{display:none!important}}
